// ABOUTME: TanStack Router configuration.
// ABOUTME: The routeTree is auto-generated by the TanStack Start Vite plugin.

import { createRouter } from '@tanstack/react-router';
import { routeTree } from './routeTree.gen';

function RoutePending() {
  return (
    <div role="status" aria-label="Loading page" className="flex min-h-[240px] w-full flex-1 items-center justify-center">
      <span
        aria-hidden="true"
        className="size-5 animate-spin rounded-full border-2 border-[var(--color-border-opaque)] border-t-[var(--color-brand)]"
      />
    </div>
  );
}

export function getRouter() {
  return createRouter({
    routeTree,
    scrollRestoration: true,
    defaultPendingComponent: RoutePending,
    defaultPendingMs: 300,
    defaultPendingMinMs: 180,
  });
}

declare module '@tanstack/react-router' {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}
